def solve():
    solutions = []
    # Search for a, b in a reasonable range
    for a in range(20):
        for b in range(20):
            val = 2**a * 5**b + 625
            n = int(val**0.5)
            if n * n == val:
                solutions.append((a, b, n))
    return solutions

print(solve())

def search_diff():
    sols = []
    for x in range(10):
        for y in range(10):
            for z in range(10):
                for w in range(10):
                    if 2**x * 5**y - 2**z * 5**w == 1:
                        sols.append((x, y, z, w))
    return sols

print(search_diff())

